import { z } from 'zod';

export { IPC } from './channels';

const dateSchema = z.object({
  year: z.number().int().min(1900).max(2200),
  month: z.number().int().min(1).max(12),
  day: z.number().int().min(1).max(31),
});

const text = z.string().max(300);

export const reportFormSchema = z.object({
  type: z.enum(['inicial', 'comparativo']),
  nombre: text,
  apellido: text,
  fechaInicial: dateSchema.nullable(),
  fechaFinal: dateSchema.nullable(),
  injuries: z.object({ tension: text, tendon: text, ligamento: text, otras: text }),
});

/** Photo ids are generated by main (uuid v4); the renderer only echoes them back. */
export const photoIdSchema = z.uuid();

export const createReportSchema = z.object({
  form: reportFormSchema,
  inicial: z.array(photoIdSchema).max(21),
  final: z.array(photoIdSchema).max(21),
});
export type CreateReportRequest = z.infer<typeof createReportSchema>;

/** Absolute file paths dropped by the user (validated again on disk in main). */
export const importSchema = z.object({
  paths: z.array(z.string().min(1).max(4096)).min(1).max(100),
});

export const releaseSchema = z.object({ ids: z.array(photoIdSchema).max(100) });

/** Only edit URLs on canva.com may be opened. */
export const openUrlSchema = z.object({
  url: z
    .url()
    .refine((u) => {
      try {
        const p = new URL(u);
        return p.protocol === 'https:' && (p.hostname === 'www.canva.com' || p.hostname === 'canva.com');
      } catch {
        return false;
      }
    }, 'URL no permitida'),
});

export interface ImportedPhoto {
  id: string;
  name: string;
  thumbDataUrl: string;
}

export interface ImportResult {
  photos: ImportedPhoto[];
  rejected: { name: string; reason: 'format' | 'size' | 'unreadable' }[];
}

export interface AuthStatus {
  connected: boolean;
  userName: string | null;
  mock: boolean;
}

export type ProgressStage = 'photos' | 'copy' | 'upload' | 'edit' | 'commit' | 'done';
export interface ProgressEvent {
  stage: ProgressStage;
  /** 0..1 overall */
  fraction: number;
  detail?: string;
}

export type ErrorCode =
  | 'notConnected'
  | 'loginCancelled'
  | 'network'
  | 'canva'
  | 'template'
  | 'photo'
  | 'model'
  | 'unknown';

export type CreateReportResult =
  | { ok: true; editUrl: string; designId: string; title: string }
  | { ok: false; code: ErrorCode; message?: string };

/** API exposed on window.drquiro by the preload script. */
export interface DrQuiroApi {
  authStatus(): Promise<AuthStatus>;
  connect(): Promise<AuthStatus & { error?: ErrorCode }>;
  disconnect(): Promise<AuthStatus>;
  /** Paths for File objects dropped from the OS (via webUtils). */
  pathsForFiles(files: File[]): string[];
  importPhotos(paths: string[]): Promise<ImportResult>;
  pickPhotos(): Promise<ImportResult>;
  releasePhotos(ids: string[]): Promise<void>;
  createReport(req: CreateReportRequest): Promise<CreateReportResult>;
  openReport(url: string): Promise<void>;
  onProgress(cb: (e: ProgressEvent) => void): () => void;
  onImportProgress(cb: (e: { done: number; total: number }) => void): () => void;
  onAuthChanged(cb: (s: AuthStatus) => void): () => void;
}
